@MvPolynomial.support_weightedHomogeneousComponent : ∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R]
  {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} [inst_2 : DecidableEq M] (n : M) (p : MvPolynomial σ R),
  ((MvPolynomial.weightedHomogeneousComponent w n) p).support = {c ∈ p.support | (Finsupp.weight w) c = n}

@MvPolynomial.IsWeightedHomogeneous.mul : ∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3}
  [inst_1 : AddCommMonoid M] {φ ψ : MvPolynomial σ R} {m n : M} {w : σ → M},
  MvPolynomial.IsWeightedHomogeneous w φ m →
    MvPolynomial.IsWeightedHomogeneous w ψ n → MvPolynomial.IsWeightedHomogeneous w (φ * ψ) (m + n)
